using FirebirdSql.Data.FirebirdClient;
using System.Globalization;
var cs="User=SYSDBA;Password=masterkey;DataSource=servern3;Port=53052;Database=C:\\Fortes\\AC\\AC.fdb;Charset=ISO8859_1;Dialect=3;ServerType=0;";
await using var c=new FbConnection(cs);await c.OpenAsync();
async Task Show(string title,string sql){Console.WriteLine("\n-- "+title+" --");await using var cmd=new FbCommand(sql,c);cmd.CommandTimeout=120;await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())Console.WriteLine(string.Join(" | ",Enumerable.Range(0,r.FieldCount).Select(i=>$"{r.GetName(i)}={r.GetValue(i)}")));}
await Show("CAMPOS FISCAIS PNM E PNC","SELECT TRIM(RDB$RELATION_NAME) TABELA,TRIM(RDB$FIELD_NAME) CAMPO FROM RDB$RELATION_FIELDS WHERE TRIM(RDB$RELATION_NAME) IN ('PNM','PNC') AND (UPPER(RDB$FIELD_NAME) CONTAINING 'ICMS' OR UPPER(RDB$FIELD_NAME) CONTAINING 'ISENT' OR UPPER(RDB$FIELD_NAME) CONTAINING 'OUTR') ORDER BY 1,RDB$FIELD_POSITION");
await Show("RESULTADO DA CONSULTA ATUAL POR CFOP","""
SELECT X.CFOP, SUM(X.VALOR) VALOR, SUM(X.BASE) BASE, SUM(X.IMPOSTO) IMPOSTO,
       SUM(CASE WHEN X.CSTB IN ('40','040','41','041') THEN X.VALOR ELSE 0 END) ISENTAS,
       CASE WHEN SUM(X.VALOR)-SUM(X.BASE)-SUM(CASE WHEN X.CSTB IN ('40','040','41','041') THEN X.VALOR ELSE 0 END)>0
            THEN SUM(X.VALOR)-SUM(X.BASE)-SUM(CASE WHEN X.CSTB IN ('40','040','41','041') THEN X.VALOR ELSE 0 END) ELSE 0 END OUTRAS
FROM (
 SELECT TRIM(p.CFO_CODIGO) CFOP,COALESCE(p.VRTOTAL,0) VALOR,COALESCE(p.ICMSBASECALC,0) BASE,
        COALESCE(p.ICMSBASECALC,0)*COALESCE(p.ICMSALIQ,0)/100 IMPOSTO,TRIM(COALESCE(p.CSTB,'')) CSTB
 FROM NFM n JOIN PNM p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NFM_SEQ=n.SEQ
 WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTENTRADASAIDA>='2026-06-01' AND n.DTENTRADASAIDA<'2026-07-01'
 UNION ALL
 SELECT TRIM(p.CFO_CODIGO),COALESCE(p.VRTOTAL,0),COALESCE(p.ICMSBASECALC,0),
        COALESCE(p.ICMSBASECALC,0)*COALESCE(p.ICMSALIQ,0)/100,TRIM(COALESCE(p.CSTB,''))
 FROM NVC n JOIN PNC p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NVC_SEQ=n.SEQ
 WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTEMISSAO>='2026-06-01' AND n.DTEMISSAO<'2026-07-01' AND SUBSTRING(TRIM(n.CHAVEELET) FROM 21 FOR 2)='65'
) X GROUP BY X.CFOP ORDER BY X.CFOP
""");
await Show("PNM POR CFOP E TRIBUTACAO","SELECT TRIM(p.CFO_CODIGO) CFOP,p.ICMSTRIBUTACAO,TRIM(COALESCE(p.CSTB,'')) CSTB,COUNT(*) QTD,SUM(p.VRTOTAL) VALOR,SUM(p.ICMSBASECALC) BASE,SUM(p.ICMSBASECALC*p.ICMSALIQ/100) ICMS FROM NFM n JOIN PNM p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NFM_SEQ=n.SEQ WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTENTRADASAIDA>='2026-06-01' AND n.DTENTRADASAIDA<'2026-07-01' GROUP BY p.CFO_CODIGO,p.ICMSTRIBUTACAO,p.CSTB ORDER BY 1,2,3");
await Show("PNC POR CFOP E TRIBUTACAO","SELECT TRIM(p.CFO_CODIGO) CFOP,p.ICMSTRIBUTACAO,TRIM(COALESCE(p.CSTB,'')) CSTB,COUNT(*) QTD,SUM(p.VRTOTAL) VALOR,SUM(p.ICMSBASECALC) BASE,SUM(p.ICMSBASECALC*p.ICMSALIQ/100) ICMS FROM NVC n JOIN PNC p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NVC_SEQ=n.SEQ WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTEMISSAO>='2026-06-01' AND n.DTEMISSAO<'2026-07-01' AND SUBSTRING(TRIM(n.CHAVEELET) FROM 21 FOR 2)='65' GROUP BY p.CFO_CODIGO,p.ICMSTRIBUTACAO,p.CSTB ORDER BY 1,2,3");
await Show("CAMPOS DE VALOR PNM","SELECT TRIM(RDB$FIELD_NAME) CAMPO FROM RDB$RELATION_FIELDS WHERE TRIM(RDB$RELATION_NAME)='PNM' AND (UPPER(RDB$FIELD_NAME) CONTAINING 'FRETE' OR UPPER(RDB$FIELD_NAME) CONTAINING 'SEGURO' OR UPPER(RDB$FIELD_NAME) CONTAINING 'DESCON' OR UPPER(RDB$FIELD_NAME) CONTAINING 'DESPESA' OR UPPER(RDB$FIELD_NAME) IN ('VRTOTAL','VRBRUTO')) ORDER BY RDB$FIELD_POSITION");
await Show("COMPOSICAO PNM","SELECT TRIM(p.CFO_CODIGO) CFOP,p.ICMSTRIBUTACAO,SUM(p.VRTOTAL) VRTOTAL,SUM(COALESCE(p.VRFRETE,0)) FRETE,SUM(COALESCE(p.VRSEGURO,0)) SEGURO,SUM(COALESCE(p.VROUTRASDESPESAS,0)) OUTRAS_DESP,SUM(COALESCE(p.VRDESCONTO,0)) DESCONTO FROM NFM n JOIN PNM p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NFM_SEQ=n.SEQ WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTENTRADASAIDA>='2026-06-01' AND n.DTENTRADASAIDA<'2026-07-01' GROUP BY p.CFO_CODIGO,p.ICMSTRIBUTACAO ORDER BY 1,2");
await Show("CAMPOS IPI ST PNM","SELECT TRIM(RDB$FIELD_NAME) CAMPO FROM RDB$RELATION_FIELDS WHERE TRIM(RDB$RELATION_NAME)='PNM' AND (UPPER(RDB$FIELD_NAME) CONTAINING 'IPI' OR UPPER(RDB$FIELD_NAME) CONTAINING 'SUBST') ORDER BY RDB$FIELD_POSITION");
await Show("VALOR CONTABIL FORMULA","SELECT TRIM(p.CFO_CODIGO) CFOP,p.ICMSTRIBUTACAO,SUM(p.VRTOTAL+COALESCE(p.IPIVR,0)+COALESCE(p.ICMSSUBSTVR,0)+COALESCE(p.VRFRETE,0)+COALESCE(p.VRSEGURO,0)+COALESCE(p.VROUTRASDESPESAS,0)) CONTABIL,SUM(COALESCE(p.IPIVR,0)) IPI,SUM(COALESCE(p.ICMSSUBSTVR,0)) ST FROM NFM n JOIN PNM p ON p.EMP_CODIGO=n.EMP_CODIGO AND p.NFM_SEQ=n.SEQ WHERE TRIM(n.EMP_CODIGO)='0158' AND TRIM(n.EST_CODIGO)='0001' AND COALESCE(n.CANCELADO,0)=0 AND n.DTENTRADASAIDA>='2026-06-01' AND n.DTENTRADASAIDA<'2026-07-01' GROUP BY p.CFO_CODIGO,p.ICMSTRIBUTACAO ORDER BY 1,2");
